    'prepare' {
      $t = Get-Target $a['window'] $a['pid']
      if (-not $t) { Out-Json ([ordered]@{ ok = $false; action = 'prepare'; error = 'window-not-found' }); break }
      $h = $t.MainWindowHandle
      $before = Ensure-Foreground $h
      if ($a.ContainsKey('width') -and $a.ContainsKey('height')) {
