      $snap['ok'] = $true
      $snap['action'] = 'prepare'
      $snap['before'] = $before
      $snap['pid'] = $t.Id
      Out-Json $snap
    }

    'click' {
      $t = Get-Target $a['window'] $a['pid']
      if (-not $t) { Out-Json ([ordered]@{ ok = $false; action = 'click'; error = 'window-not-found' }); break }
      $h = $t.MainWindowHandle
      $fx = [int]$a['x']
      $fy = [int]$a['y']
